using System;
using System.Collections.Generic;
using UnityEngine;

namespace CarWash.Data
{
    /// <summary>id → asset lookup for all generated data. Generated by DataBuilder, assigned to Bootstrap.</summary>
    public class DataRegistry : ScriptableObject
    {
        public BalanceData balance;
        public ToolData[] tools = Array.Empty<ToolData>();
        public VehicleData[] vehicles = Array.Empty<VehicleData>();
        public CritterData[] critters = Array.Empty<CritterData>();
        public UpgradeData[] upgrades = Array.Empty<UpgradeData>();
        public WeekData[] weeks = Array.Empty<WeekData>();

        Dictionary<string, ScriptableObject> _byId;

        public T Get<T>(string id) where T : ScriptableObject
        {
            if (_byId == null) BuildIndex();
            return id != null && _byId.TryGetValue(id, out var so) ? so as T : null;
        }

        void BuildIndex()
        {
            _byId = new Dictionary<string, ScriptableObject>();
            foreach (var t in tools) _byId[t.id] = t;
            foreach (var v in vehicles) _byId[v.id] = v;
            foreach (var c in critters) _byId[c.id] = c;
            foreach (var u in upgrades) _byId[u.id] = u;
            foreach (var w in weeks) _byId[w.id] = w;
        }

        void OnEnable() => _byId = null;
    }
}
